func (providerInstance *openstackProvider) locateResource(resourceNameParam string) (*glance.ImageDetail, error) {
	bestImage := glance.ImageDetail{}
	var mostRecentCreation time.Time
	imageCollection, retrievalError := providerInstance.getActiveImages()
	if retrievalError != nil {
		return nil, fmt.Errorf("cannot get the active images list: %v", &openstackError{retrievalError})
	}
	firstStage := func() (*glance.ImageDetail, bool) {
		idx := 0
		for idx < len(imageCollection) {
			img := imageCollection[idx]
			if img.Name == resourceNameParam {
				debugf("Name match: %#v matches %#v", resourceNameParam, img)
				return &img, true
			}
			idx++
		}
		return nil, false
	}
	if found, ok := firstStage(); ok {
		return found, nil
	}
	terms := toTerms(resourceNameParam)
	prefixMatches := make([]glance.ImageDetail, 0)
	for _, img := range imageCollection {
		if strings.HasPrefix(img.Name, resourceNameParam) {
			debugf("Prefix match: %#v matches %#v", resourceNameParam, img)
			prefixMatches = append(prefixMatches, img)
		}
	}
	if len(prefixMatches) > 0 {
		bestImage, mostRecentCreation = selectNewest(prefixMatches)
		if bestImage.Id != "" {
			return &bestImage, nil
		}
	}
	termMatches := make([]glance.ImageDetail, 0)
	for _, img := range imageCollection {
		imgTerms := toTerms(img.Name)
		if containsTerms(imgTerms, terms) {
			debugf("Terms match: %#v matches %#v", resourceNameParam, img)
			termMatches = append(termMatches, img)
		}
	}
	if len(termMatches) > 0 {
		bestImage, mostRecentCreation = selectNewest(termMatches)
		if bestImage.Id != "" {
			return &bestImage, nil
		}
	}
	return nil, &FatalError{fmt.Errorf("cannot find matching image for %q", resourceNameParam)}
}
func selectNewest(imgSlice []glance.ImageDetail) (glance.ImageDetail, time.Time) {
	result := glance.ImageDetail{}
	var recentTime time.Time
	for _, img := range imgSlice {
		parsedTime, err := time.Parse(time.RFC3339, img.Created)
		if err != nil {
			parsedTime = time.Time{}
		}
		if result.Id == "" || parsedTime.After(recentTime) {
			debugf("Newer match found: %#v", img)
			result = img
			recentTime = parsedTime
		}
	}
	return result, recentTime
}

