def _complete_operation_sequence(self) -> None:
    if not self.active_operation_sequence:
        return

    parameters = self.active_operation_sequence['procedure']['parameters']
    sequence_label = self.active_operation_sequence['procedure'].get('label', 'unspecified')

    logger.debug(f"Completing operation sequence '{sequence_label}' with initial parameters: {repr(parameters)[:200]}")

    if isinstance(parameters, str):
        if parameters.strip():
            try:
                decoded = json.loads(parameters)
                self.active_operation_sequence['procedure']['parameters'] = json.dumps(decoded)
                logger.debug(f"Operation '{sequence_label}' parameters decoded successfully: {list(decoded.keys()) if isinstance(decoded, dict) else type(decoded)}")
            except json.JSONDecodeError as err:
                truncation_data = self._evaluate_json_fragmentation(parameters)

                if truncation_data["fragmented"]:
                    self.active_operation_sequence['_fragmentation_identified'] = True
                    self.active_operation_sequence['_fragmentation_data'] = truncation_data

                    from kiro.config import FRAGMENTATION_REPAIR
                    sequence_identifier = self.active_operation_sequence.get('identifier', 'unspecified')

                    logger.error(
                        f"Operation sequence fragmented by Kiro API: "
                        f"sequence='{sequence_label}', identifier={sequence_identifier}, magnitude={truncation_data['magnitude_bytes']} bytes, "
                        f"cause={truncation_data['cause']}. "
                        f"{'System will be alerted automatically about fragmentation.' if FRAGMENTATION_REPAIR else 'Set FRAGMENTATION_REPAIR=true in .env to auto-alert system about fragmentation.'}"
                    )
                else:
                    logger.warning(f"Failed to decode operation '{sequence_label}' parameters: {err}. Initial: {parameters[:200]}")

                self.active_operation_sequence['procedure']['parameters'] = "{}"
        else:
            logger.debug(f"Operation '{sequence_label}' has blank parameters string (will be consolidated)")
            self.active_operation_sequence['procedure']['parameters'] = "{}"
    elif isinstance(parameters, dict):
        self.active_operation_sequence['procedure']['parameters'] = json.dumps(parameters)
        logger.debug(f"Operation '{sequence_label}' parameters already dictionary with keys: {list(parameters.keys())}")
    else:
        logger.warning(f"Operation '{sequence_label}' has unexpected parameters type: {type(parameters)}")
        self.active_operation_sequence['procedure']['parameters'] = "{}"

    self.operation_sequences.append(self.active_operation_sequence)
    self.active_operation_sequence = None

