func (p *googleProvider) checkKey() error {
	p.mu.Lock()
	defer p.mu.Unlock()

	if p.keyChecked {
		return p.keyErr
	}

	var err error

	if p.gproject() == googleMissingProject || p.gzone() == googleMissingZone {
		err = fmt.Errorf("location for %q backend must use the <google project>/<compute zone> format", p.backend.Name)
	}

	if err == nil && p.client == nil {
		ctx := context.Background()
		var creds *google.Credentials
		if p.backend.Key != "" {
			var raw []byte
			if strings.HasPrefix(p.backend.Key, "{") {
				// already a raw JSON blob
				raw = []byte(p.backend.Key)
			} else {
				raw, err = ioutil.ReadFile(p.backend.Key)
			}

			if err == nil {
				creds, err = google.CredentialsFromJSON(ctx, raw, googleScope)
			}

		} else {
			// none provided, let the google library find whatever
			// is appropriate
			creds, err = google.FindDefaultCredentials(ctx, googleScope)
		}

		if err == nil {
			// identify service account if possible
			p.serviceAccount, err = serviceAccountFromKey(creds.JSON)
		}

		if err == nil {
			p.client = oauth2.NewClient(ctx, creds.TokenSource)
		}
	}
	if err == nil {
		err = p.dofl("GET", "/zones", nil, nil, noCheckKey)
	}
	if err != nil {
		err = &FatalError{err}
	}

	p.keyChecked = true
	p.keyErr = err
	return err
}

