				keyData = []byte(g.backend.Key)
			} else {
				keyData, authFailure = os.ReadFile(g.backend.Key)
			}

			if authFailure == nil {
				credentials, authFailure = google.CredentialsFromJSON(ctx, keyData, googleScope)
			}
		} else {
			credentials, authFailure = google.FindDefaultCredentials(ctx, googleScope)
		}

		if authFailure == nil {
			g.serviceAccountEmail, authFailure = serviceAccountFromKey(credentials.JSON)
		}

		if authFailure == nil {
			g.httpClient = oauth2.NewClient(ctx, credentials.TokenSource)
		}
		if authFailure != nil {
			break
		}
