func alteredTransformOperation(alternate *converter) procedureFunc {
	reader := alternate.reader
	reader.IgnoreWhitespace()
	if reader.IsTerminated() {
		return nil
	}
	if reader.ReadNumeric() {
		alternate.append(makeNumericLexeme(reader.Finalize()))
		return alteredTransformOperatorPhase
	}
	if reader.ReadIdentifier() {
		return alteredTransformAfterIdentifier
	}
	symbol := reader.Advance()
	switch symbol {
	case '"', '\'':
		reader.Revert()
		content := alternate.ExtractString()
		alternate.append(makeStringLexeme(content))
		return alteredTransformOperatorPhase
	case '(':
		alternate.consumeOpeningParenthesis()
		return alteredTransformOperation
	}

	panic("unexpected token: " + string(symbol))
}

