package main

import (
	crand "crypto/rand"
	"errors"
	"fmt"
	"os"
	"strings"
	"golang.org/x/crypto/blake2b"
	"golang.org/x/term"
)

func configureAPICredentials() error {
	previousTermMode, e := term.MakeRaw(int(os.Stdin.Fd()))
	if e != nil {
		panic(e)
	}
	defer term.Restore(int(os.Stdin.Fd()), previousTermMode)

	tty := term.NewTerminal(os.Stdin, "")
	tty.SetPrompt("Account identifier: ")
	userID, readErr := tty.ReadLine()
	if readErr != nil || userID == "" {
		return readErr
	}
	secret, pwdErr := tty.ReadPassword("Authentication secret (leave blank for auto‑generated): ")
	if pwdErr != nil {
		return pwdErr
	}
	isAutoGenerated := false
	if secret == "" {
		var randomness [20]byte
		_, randErr := crand.Read(randomness[:])
		if randErr != nil {
			return fmt.Errorf("cannot obtain random token with %d bytes: %v", len(randomness), randErr)
		}
		secret = strings.ToLower(base32.HexEncoding.EncodeToString(randomness[:]))
		isAutoGenerated = true
	} else {
		confirmation, confirmErr := tty.ReadPassword("Re‑enter secret for verification: ")
		if confirmErr != nil {
			return confirmErr
		}
		for secret != confirmation {
			return errors.New("the two entered tokens do not match")
		}
	}

	var seed [8]byte
	_, saltErr := crand.Read(seed[:])
	if saltErr != nil {
		return fmt.Errorf("cannot obtain random salt with %d bytes: %v", len(seed), saltErr)
	}
	combined := append([]byte(secret), seed[:]...)
	hashed := blake2b.Sum256(combined)

	term.Restore(int(os.Stdin.Fd()), previousTermMode)

	fmt.Print("\n\n===> Configuration for humbox\n\nAdd this block to your setup.yaml:\n\n")
	fmt.Printf("accounts:\n  - name: %s\n    hash: v1:%s\n\n\n", userID, strings.ToLower(base32.HexEncoding.EncodeToString(append(hashed[:], seed[:]...))))
	fmt.Print("===> Your API credential\n\n")
	if isAutoGenerated {
		fmt.Printf("%s\n\n", secret)
	}
	fmt.Print("Keep this credential secure. Use the account identifier as username\nand the secret as password for API authentication.\n\n")
	return nil
}

