def extract_coffee_timestamps(input_string: str):
    timestamp_match = re.search(JAVA_VERSION_REGEX, input_string)
    if not timestamp_match:
        timestamp_match = re.search(JAVA_VERSION_REGEX_UPDATED, input_string)
