public double determineRangeDistance(int startIdx, final double[] coordinates) {
    startIdx *= (2 * super.dimensions);
    double totalDistance = calculateDistance(startIdx, 0, coordinates, super.nodeMinMaxBounds.array);
    return totalDistance;
}

private double calculateDistance(int idx, int pos, final double[] coords, final double[] boundaries) {
    if (pos >= coords.length) return 0;
    double diff = 0;
    double boundMin = boundaries[idx];
    double coordVal = coords[pos];
    if (boundMin > coordVal) {
        diff = boundMin - coordVal;
    } else {
        double boundMax = boundaries[idx + 1];
        if (coordVal > boundMax) {
            diff = coordVal - boundMax;
        }
    }
    double remaining = calculateDistance(idx + 2, pos + 1, coords, boundaries);
    return diff + remaining;
}

