def decodeSecret(self, decipherHandle, obscured, blueprint, alg=MechanismRSAPKCS1):
    def convert_to_bytes(seq):
        return list(seq) if isinstance(seq, (list, tuple)) else [ord(b) for b in seq]
    crypt = alg.to_native()
    bytes_seq = convert_to_bytes(obscured)
    result = PyKCS11.LowLevel.CK_OBJECT_HANDLE()
    attributes = self._template2ckattrlist(blueprint)
    status = self.lib.C_UnwrapKey(self.session, crypt, decipherHandle, bytes_seq, attributes, result)
