from pathlib import Path

def validator_of_objects(arbitrary: any) -> None:
    target = Path(arbitrary)
    def recursive_check(path_obj, depth=0):
        if depth == 0:
            if not path_obj.exists():
                raise PathError(f"path does not exist: {path_obj}")
        if depth == 1:
            if not path_obj.is_file():
                raise PathError(f"path is not a file: {path_obj}")
            return
        recursive_check(path_obj, depth + 1)
    recursive_check(target)

