			case <-attemptTicker.C:
				break
			case <-infoTicker.C:
				logPrint("Failed to connect to %s: %v", desc, dialErr)
				break
			case <-deadlineChan:
				return fmt.Errorf("cannot connect to %s: %v", desc, dialErr)
			case <-cxt.Done():
				return fmt.Errorf("cannot connect to %s: interrupted", desc)
			}
			break
		}
	}
