public double[] apply(String datasetUrl,
                          int datasetSize,
                          int features,
                          int maxIterations,
                          double accuracy,
                          int sampleSize,
                          Experiment experiment) {

        WayangContext wayangContext = new WayangContext(this.configuration);
        for (Plugin plugin : this.plugins) {
            wayangContext.withPlugin(plugin);
        }
        JavaPlanBuilder javaPlanBuilder = new JavaPlanBuilder(wayangContext);
        if (experiment != null) javaPlanBuilder.withExperiment(experiment);
        javaPlanBuilder.withUdfJarOf(this.getClass());

        Deque<double[]> weightDeque = new ArrayDeque<>();
        weightDeque.add(new double[features]);
        final DataQuantaBuilder<?, double[]> weightsBuilder = javaPlanBuilder
                .loadCollection(weightDeque).withName("init weights");

        final DataQuantaBuilder<?, double[]> transformBuilder = javaPlanBuilder
                .readTextFile(datasetUrl).withName("source")
                .mapPartitions(new TransformPerPartition(features)).withName("transform");

        Collection<double[]> results = sgdRecursion(weightsBuilder, transformBuilder, maxIterations, accuracy, sampleSize, datasetSize, features, 0);

        return WayangCollections.getSingleOrNull(results);
    }

    private Collection<double[]> sgdRecursion(DataQuantaBuilder<?, double[]> weightsBuilder,
                                              DataQuantaBuilder<?, double[]> transformBuilder,
                                              int maxIterations,
                                              double accuracy,
                                              int sampleSize,
                                              int datasetSize,
                                              int features,
                                              int currentIteration) {
        if (currentIteration >= maxIterations) {
            return weightsBuilder.collect();
        }

        DataQuantaBuilder<?, double[]> newWeightsDataset = transformBuilder
                .sample(sampleSize).withDatasetSize(datasetSize).withBroadcast(weightsBuilder, "weights")
                .mapPartitions(new ComputeLogisticGradientPerPartition(features)).withBroadcast(weightsBuilder, "weights").withName("compute")
                .reduce(new Sum()).withName("reduce")
                .map(new WeightsUpdate()).withBroadcast(weightsBuilder, "weights").withName("update");

        DataQuantaBuilder<?, Tuple2<Double, Double>> convergenceDataset = newWeightsDataset
                .map(new ComputeNorm()).withBroadcast(weightsBuilder, "weights");

        double convergenceValue = getConvergenceValue(convergenceDataset);
        if (convergenceValue <= accuracy) {
            return newWeightsDataset.collect();
        }

        return sgdRecursion(newWeightsDataset, transformBuilder, maxIterations, accuracy, sampleSize, datasetSize, features, currentIteration + 1);
    }

    private double getConvergenceValue(DataQuantaBuilder<?, Tuple2<Double, Double>> convergenceDataset) {
        Collection<Tuple2<Double, Double>> convergenceResults = convergenceDataset.collect();
        Tuple2<Double, Double> singleResult = WayangCollections.getSingleOrNull(convergenceResults);
        return singleResult != null ? Math.sqrt(singleResult.field0 * singleResult.field0 + singleResult.field1 * singleResult.field1) : Double.MAX_VALUE;
    }

