	processDimensions := func(width int, height int) (int, int) {
		if width == 0 && height == 0 {
			return DiscordStickerSize, DiscordStickerSize
		}
		if width > DiscordStickerSize || height > DiscordStickerSize {
			if width > height {
				height = height / (width / DiscordStickerSize)
				width = DiscordStickerSize
			} else if width < height {
				width = width / (height / DiscordStickerSize)
				height = DiscordStickerSize
			} else {
				width, height = DiscordStickerSize, DiscordStickerSize
			}
		}
		return width, height
	}
	payload.Info.Width, payload.Info.Height = processDimensions(payload.Info.Width, payload.Info.Height)
}

